import itertools, numpy as np, sys
l,m=21,18
A=[(3,0),(0,10),(0,17)]; B=[(0,5),(3,0),(19,0)]
def img(sig,mono):  # sigma: x->x^a y^b, y->x^c y^d ; monomial x^p y^q
    a,b,c,d=sig; p,q=mono
    return ((a*p+c*q)%l,(b*p+d*q)%m)
def mul(g,P): return frozenset(((p+g[0])%l,(q+g[1])%m) for p,q in P)
auts=[]
for a in range(l):
  for b in (0,6,12):
    for c in (0,7,14):
      for d in range(m):
        sig=(a,b,c,d)
        pts=set(img(sig,(i,j)) for i in range(l) for j in range(m))
        if len(pts)==l*m: auts.append(sig)
print("Aut(Z21xZ18) order",len(auts))
FA,FB=frozenset(A),frozenset(B)
found=[]
for sig in auts:
    sA=[img(sig,t) for t in A]; sB=[img(sig,t) for t in B]
    for swap in (0,1):
        tA,tB=(sA,sB) if not swap else (sB,sA)   # need g*tA=A, g*tB=B
        for t in A:
            g=((t[0]-tA[0][0])%l,(t[1]-tA[0][1])%m)
            if mul(g,tA)==FA and mul(g,tB)==FB: found.append((sig,swap,g)); break
print("symmetries mod translations:",len(found))
for f in found: print(f)
