for sig,swap,g in found:
    perm=np.zeros(n,dtype=int)
    for blk in (0,1):
        for i in range(l):
            for j in range(m):
                (p,q)=img(sig,(i,j)); p=(p+g[0])%l; q=(q+g[1])%m
                perm[blk*lm+i*m+j]=((blk^swap)*lm)+p*m+q
    # vector v -> v' with v'[perm[t]]=v[t]
    Kp=np.zeros_like(K); Kp[:,perm]=K
    ok1=not (hx@Kp.T%2).any()
    Hp=np.zeros_like(hz); Hp[:,perm]=hz
    ok2=distance.rank(np.vstack([hz,Hp]))==rZ
    print(sig,swap,g,"ker preserved",ok1,"rowspace preserved",ok2)
