import numpy as np, sys
sys.path.insert(0,'qd'); import distance
l,m=21,18; A=[(3,0),(0,10),(0,17)]; B=[(0,5),(3,0),(19,0)]
hx,hz=distance.check_matrices(A,B,l,m); n=2*l*m; lm=l*m
# vertices: qubits 0..n-1, X-checks n..n+lm-1, Z-checks n+lm..n+2lm-1
V=n+2*lm; adj=[[] for _ in range(V)]
for r in range(lm):
    for q in np.flatnonzero(hx[r]): adj[q].append(n+r); adj[n+r].append(q)
    for q in np.flatnonzero(hz[r]): adj[q].append(n+lm+r); adj[n+lm+r].append(q)
base=[0]*n+[1]*lm+[2]*lm
def refine(col):
    col=list(col)
    while True:
        sig=[(col[v],tuple(sorted(col[u] for u in adj[v]))) for v in range(V)]
        keys={s:i for i,s in enumerate(sorted(set(sig)))}
        new=[keys[s] for s in sig]
        if len(set(new))==len(set(col)): return new
        col=new
def indiv(v):
    c=list(base); c[v]=3; return refine(c)
c0=indiv(0); print("cells after individualizing qubit 0:",len(set(c0)),"of",V)
# orbit of qubit 0: targets t whose refined coloring is discrete and the color-matching map is an automorphism
def perm_from(ca,cb):
    pos={c:v for v,c in enumerate(cb)}; return [pos[c] for c in ca]
S=set(); 
for t in range(n):
    ct=indiv(t)
    if sorted(ct)!=sorted(c0): continue
    p=perm_from(c0,ct)  # maps vertex v (color in c0) to vertex with same color in ct
    ok=all(sorted(p[u] for u in adj[v])==sorted(adj[p[v]]) for v in range(V))
    if ok: S.add(t)
print("orbit of qubit 0 under Aut(Tanner graph): size",len(S), "left block:",sum(t<lm for t in S),"right:",sum(t>=lm for t in S))
